const results = await Promise.allSettled([
  tools.exec_command({cmd:"git status --short --branch","max_output_tokens":3000}),
  tools.exec_command({cmd:"rg --files -g AGENTS.md -g composer.json -g composer.lock -g 'phpstan*' -g 'phpunit*' -g '*rector*' -g '*cs-fixer*' -g '*pint*' -g 'Makefile' -g '.github/workflows/*' -g '*guard*' -g '!vendor' -g '!node_modules' -g '!docs/site' --hidden","max_output_tokens":6000}),
  tools.exec_command({cmd:"ls -la .github/workflows && cat composer.json","max_output_tokens":6000})
]); results.forEach((r,i)=>text({i,...r}));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat AGENTS.md .github/workflows/ci.yml .github/workflows/mutation.yml","max_output_tokens":9500}),
  tools.exec_command({cmd:"ls -la && rg --files scripts .agents -g '!vendor' -g '!node_modules' && for file in packages/*/composer.json; do echo \"$file\"; cat \"$file\"; done","max_output_tokens":16000}),
  tools.exec_command({cmd:"php -v && composer --version && git log -4 --oneline","max_output_tokens":3000})
]);results.forEach((r,i)=>text({i,...r}));

const results=await Promise.allSettled([
 tools.exec_command({cmd:"for file in packages/*/composer.json; do echo \"$file\"; cat \"$file\"; done","max_output_tokens":17000}),
 tools.exec_command({cmd:"cat /Users/ab/.agents/skills/find-docs/SKILL.md && rg --files packages projects -g AGENTS.md -g '*deptrac*' -g '*compat*' -g 'guard.yaml' -g '!vendor' --hidden","max_output_tokens":6500})
]);results.forEach((r,i)=>text({i,...r}));

